1	import { Link, useParams } from "react-router-dom";
2	import { CaseHeader } from "../components/CaseHeader";
3	import { CostTrust } from "../components/CostTrust";
4	import { EvidenceTabs } from "../components/EvidenceTabs";
5	import { FindingsSection } from "../components/FindingsSection";
6	import { ProgressPanel } from "../components/ProgressPanel";
7	import { QuestionsSection } from "../components/QuestionsSection";
8	import { SignalsSection } from "../components/SignalsSection";
9	import { StepTimeline } from "../components/StepTimeline";
10	import { SummaryCard } from "../components/SummaryCard";
11	import { EmptyBox, ErrorBox, Loading, SectionHead } from "../components/ui";
12	import { useCase, useDocumentTitle } from "../lib/hooks";
13	
14	export function CaseDetail() {
15	  const { id = "" } = useParams<{ id: string }>();
16	  const { data, error, loading, refresh } = useCase(id);
17	  useDocumentTitle(data ? `${data.target} investigation` : "Case");
18	
19	  if (loading && !data) {
20	    return <Loading label="Loading case..." />;
21	  }
22	  if (!data) {
23	    return (
24	      <>
25	        <ErrorBox title="Could not load this case" message={error ?? "The case was not found."} onRetry={refresh} />
26	        <p style={{ marginTop: 14 }}>
27	          <Link to="/cases">Back to all cases</Link>
28	        </p>
29	      </>
30	    );
31	  }
32	
33	  const v = data;
34	  return (
35	    <>
36	      <p className="small" style={{ marginBottom: 10 }}>
37	        <Link to="/cases">All cases</Link>
38	      </p>
39	      {error ? (
40	        <div style={{ marginBottom: 12 }}>
41	          <ErrorBox title="Live updates interrupted" message={`${error} Retrying automatically.`} />
42	        </div>
43	      ) : null}
44	
45	      <CaseHeader view={v} onResumed={refresh} />
46	
47	      {v.running ? <ProgressPanel view={v} /> : null}
48	
49	      <div className="section" style={{ marginTop: 16 }}>
50	        <SummaryCard assessment={v.assessment} running={v.running} />
51	      </div>
52	
53	      <SignalsSection signals={v.signals} />
54	      <FindingsSection findings={v.findings} />
55	      <QuestionsSection questions={v.questions} />
56	
57	      <section className="section" aria-labelledby="steps-h">
58	        <SectionHead
59	          id="steps-h"
60	          title="How the agent investigated"
61	          subtitle="A step-by-step record. The AI planner chooses what to look up; the rule-based planner is the fixed fallback; the system handles everything else."
62	        />
63	        <div className="card">
64	          {v.steps.length === 0 ? (
65	            <EmptyBox>No steps have been recorded yet.</EmptyBox>
66	          ) : (
67	            <StepTimeline steps={v.steps} />
68	          )}
69	        </div>
70	      </section>
71	
72	      <EvidenceTabs companies={v.companies} people={v.people} jobs={v.jobs} />
73	      <CostTrust
74	        credits={v.credits}
75	        verification={v.verification}
76	        llmModel={v.llm_model}
77	        traceIds={v.trace_ids}
78	        synthetic={v.synthetic}
79	        planComparison={v.plan_comparison}
80	      />
81	    </>
82	  );
83	}
84

1	import type {
2	  CaseListItem,
3	  CaseView,
4	  CreateCaseRequest,
5	  CreateCaseResponse,
6	  EvidenceSummary,
7	  FaultOption,
8	  FeaturedCase,
9	  IdentityResult,
10	  Scenario,
11	  StatusResponse,
12	} from "./types";
13	
14	export class ApiError extends Error {
15	  status: number;
16	  constructor(message: string, status: number) {
17	    super(message);
18	    this.name = "ApiError";
19	    this.status = status;
20	  }
21	}
22	
23	const USE_MOCKS = import.meta.env.VITE_USE_MOCKS === "true";
24	
25	async function request<T>(path: string, init?: RequestInit): Promise<T> {
26	  let res: Response;
27	  try {
28	    res = await fetch(path, {
29	      ...init,
30	      headers: {
31	        Accept: "application/json",
32	        ...(init?.body ? { "Content-Type": "application/json" } : {}),
33	        ...(init?.headers ?? {}),
34	      },
35	    });
36	  } catch {
37	    throw new ApiError(
38	      "Could not reach the DealScope server. Check that it is running and try again.",
39	      0,
40	    );
41	  }
42	  if (!res.ok) {
43	    let detail = `Request failed (HTTP ${res.status}).`;
44	    try {
45	      const body: unknown = await res.json();
46	      if (body && typeof body === "object" && "detail" in body) {
47	        const d = (body as { detail: unknown }).detail;
48	        if (typeof d === "string" && d.length > 0) detail = d;
49	        else if (Array.isArray(d) && d.length > 0) {
50	          detail = d
51	            .map((item: unknown) =>
52	              item && typeof item === "object" && "msg" in item
53	                ? String((item as { msg: unknown }).msg)
54	                : String(item),
55	            )
56	            .join("; ");
57	        }
58	      }
59	    } catch {
60	      /* non-JSON error body: keep the generic message */
61	    }
62	    throw new ApiError(detail, res.status);
63	  }
64	  try {
65	    return (await res.json()) as T;
66	  } catch {
67	    throw new ApiError("The server returned an unreadable response.", res.status);
68	  }
69	}
70	
71	function post<T>(path: string, body?: unknown): Promise<T> {
72	  return request<T>(path, {
73	    method: "POST",
74	    body: body === undefined ? undefined : JSON.stringify(body),
75	  });
76	}
77	
78	// Mocks are loaded lazily and only when VITE_USE_MOCKS is "true"; the condition is a
79	// build-time constant so production bundles drop the mock code entirely.
80	const loadMocks = () => import("../mocks/mockApi");
81	
82	export const api = {
