42	export function formatDate(iso: string | null | undefined): string {
43	  const d = parseDate(iso);
44	  if (!d) return iso ? iso : "n/a";
45	  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
46	}
47	
48	export function formatDateTime(iso: string | null | undefined): string {
49	  const d = parseDate(iso);
50	  if (!d) return iso ? iso : "n/a";
51	  return d.toLocaleString("en-US", {
52	    month: "short",
53	    day: "numeric",
54	    hour: "numeric",
55	    minute: "2-digit",
56	  });
57	}
58	
59	export function formatTime(iso: string | null | undefined): string {
60	  const d = parseDate(iso);
61	  if (!d) return "";
62	  return d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", second: "2-digit" });
63	}
64	
65	export function formatRelative(iso: string | null | undefined, now: number = Date.now()): string {
66	  const d = parseDate(iso);
67	  if (!d) return "n/a";
68	  const diff = Math.round((now - d.getTime()) / 1000);
69	  if (diff < 0) return "just now";
70	  if (diff < 45) return "just now";
71	  if (diff < 90) return "a minute ago";
72	  const mins = Math.round(diff / 60);
73	  if (mins < 60) return `${mins} minutes ago`;
74	  const hours = Math.round(mins / 60);
75	  if (hours < 24) return hours === 1 ? "1 hour ago" : `${hours} hours ago`;
76	  const days = Math.round(hours / 24);
77	  if (days < 30) return days === 1 ? "yesterday" : `${days} days ago`;
78	  return formatDate(iso);
79	}
