91	/** Normalize a user-entered domain: strip protocol, www, paths, whitespace, lowercase. */
92	export function normalizeDomain(raw: string): string {
93	  let s = raw.trim().toLowerCase();
94	  s = s.replace(/^[a-z]+:\/\//, "");
95	  s = s.replace(/^www\./, "");
96	  s = s.split(/[/?#]/)[0] ?? "";
97	  return s.replace(/[,;]+$/, "");
98	}
