100	const DOMAIN_RE = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;
101	
102	export function isValidDomain(d: string): boolean {
103	  return DOMAIN_RE.test(d);
104	}
105	
106	export function splitDomains(text: string): string[] {
107	  return text
108	    .split(/[\s,;]+/)
109	    .map(normalizeDomain)
110	    .filter((d) => d.length > 0);
111	}
