1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { api, errorMessage } from "../api/client";
3	import type { CaseView } from "../api/types";
4	
5	export interface AsyncState<T> {
6	  data: T | null;
7	  error: string | null;
8	  loading: boolean;
9	  reload: () => void;
10	}
11	
12	/** Load data once on mount (and whenever `reload` is called). Ignores results after unmount. */
13	export function useAsync<T>(loader: () => Promise<T>): AsyncState<T> {
14	  const [data, setData] = useState<T | null>(null);
15	  const [error, setError] = useState<string | null>(null);
16	  const [loading, setLoading] = useState(true);
17	  const [tick, setTick] = useState(0);
18	  const loaderRef = useRef(loader);
19	  loaderRef.current = loader;
20	
21	  useEffect(() => {
22	    let cancelled = false;
23	    setLoading(true);
24	    setError(null);
25	    loaderRef.current().then(
26	      (d) => {
27	        if (cancelled) return;
28	        setData(d);
29	        setLoading(false);
30	      },
31	      (e: unknown) => {
32	        if (cancelled) return;
33	        setError(errorMessage(e));
34	        setLoading(false);
35	      },
36	    );
37	    return () => {
38	      cancelled = true;
39	    };
40	  }, [tick]);
41	
42	  const reload = useCallback(() => setTick((t) => t + 1), []);
43	  return { data, error, loading, reload };
44	}
45	
46	const POLL_MS = 1500;
47	
48	export interface CaseState {
49	  data: CaseView | null;
50	  error: string | null;
51	  loading: boolean;
52	  refresh: () => void;
53	}
54	
55	/**
56	 * Fetches a case and keeps polling every ~1.5 s while the case reports running = true.
57	 * Exactly one timer exists at a time and it is cleared on unmount or id change.
58	 */
59	export function useCase(id: string): CaseState {
60	  const [data, setData] = useState<CaseView | null>(null);
61	  const [error, setError] = useState<string | null>(null);
62	  const [loading, setLoading] = useState(true);
63	  const [kick, setKick] = useState(0);
64	
65	  useEffect(() => {
66	    let cancelled = false;
67	    let timer: number | undefined;
68	    let lastRunning = false;
69	
70	    const run = async () => {
71	      try {
72	        const view = await api.getCase(id);
73	        if (cancelled) return;
74	        setData(view);
75	        setError(null);
76	        setLoading(false);
77	        lastRunning = view.running;
78	        if (view.running) {
79	          timer = window.setTimeout(run, POLL_MS);
80	        }
81	      } catch (e) {
82	        if (cancelled) return;
83	        setError(errorMessage(e));
84	        setLoading(false);
85	        // Keep trying while we previously saw a running case; a transient failure should not freeze the page.
86	        if (lastRunning) timer = window.setTimeout(run, POLL_MS * 3);
87	      }
88	    };
89	
90	    setLoading(true);
91	    run();
92	    return () => {
93	      cancelled = true;
94	      if (timer !== undefined) window.clearTimeout(timer);
95	    };
96	  }, [id, kick]);
97	
98	  const refresh = useCallback(() => setKick((k) => k + 1), []);
99	  return { data, error, loading, refresh };
100	}
101	
102	/** Re-render periodically so relative timestamps stay fresh. */
103	export function useNow(intervalMs = 30000): number {
104	  const [now, setNow] = useState(() => Date.now());
105	  useEffect(() => {
106	    const t = window.setInterval(() => setNow(Date.now()), intervalMs);
107	    return () => window.clearInterval(t);
108	  }, [intervalMs]);
109	  return now;
110	}
111	
112	export function useDocumentTitle(title: string): void {
113	  useEffect(() => {
114	    document.title = title ? `${title} - DealScope` : "DealScope";
115	  }, [title]);
116	}
