113	.topbar { background: var(--navy); color: var(--navy-ink); position: sticky; top: 0; z-index: 30; }
114	.topbar-inner {
115	  max-width: 1160px; margin: 0 auto; padding: 10px 16px; display: flex; align-items: center;
116	  gap: 8px 24px; flex-wrap: wrap;
117	}
118	.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: inherit; }
119	.brand-mark { flex: none; }
120	.brand-name { font-weight: 700; font-size: 1.15rem; letter-spacing: 0.01em; display: block; line-height: 1.1; }
121	.brand-tag { font-size: 0.75rem; opacity: 0.8; display: block; }
122	.nav { display: flex; gap: 4px; flex-wrap: wrap; flex: 1; }
123	.nav a {
124	  color: #d6deee; text-decoration: none; padding: 7px 12px; border-radius: var(--radius-sm); font-weight: 500;
125	  font-size: 0.93rem;
126	}
127	.nav a:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
128	.nav a.active { background: rgba(255, 255, 255, 0.16); color: #fff; }
129	.topbar :focus-visible { outline-color: #9ec1ff; }
130	
131	.systems { position: relative; }
132	.systems-btn {
133	  display: inline-flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.1); color: #fff;
134	  border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 999px; padding: 6px 12px; font: inherit;
135	  font-size: 0.85rem; cursor: pointer;
136	}
137	.systems-btn:hover { background: rgba(255, 255, 255, 0.18); }
138	.systems-panel {
139	  position: absolute; right: 0; top: calc(100% + 8px); width: min(360px, calc(100vw - 32px));
140	  background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: var(--radius);
141	  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25); padding: 14px; z-index: 40;
142	}
143	.systems-panel h2 { font-size: 0.95rem; margin-bottom: 8px; }
144	.system-row { display: flex; gap: 10px; align-items: flex-start; padding: 7px 0; border-top: 1px solid var(--line); }
145	.system-row:first-of-type { border-top: 0; }
146	.system-label { font-weight: 600; font-size: 0.9rem; }
147	.system-detail { font-size: 0.82rem; color: var(--muted); }
148	.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; flex: none; margin-top: 6px; }
149	.dot.on { background: #3fcf8e; }
150	.dot.off { background: transparent; border: 2px solid #f0a0a0; }
151	.systems-btn .dot { margin-top: 0; }
152	.dots { display: inline-flex; gap: 4px; }
153	
154	.main { max-width: 1160px; margin: 0 auto; padding: 24px 16px 64px; }
155	.page-head { margin-bottom: 20px; }
156	.page-head p { color: var(--muted); max-width: 70ch; margin-bottom: 0; }
157	.footer { text-align: center; color: var(--muted); font-size: 0.82rem; padding: 0 16px 32px; }
158	
159	/* Cards, buttons */
160	.card {
161	  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
162	  padding: 20px; box-shadow: var(--shadow);
163	}
164	.card + .card, .stack > * + * { margin-top: 16px; }
165	.card h2 { margin-bottom: 0.4em; }
166	.section { margin-top: 28px; }
167	.section-head { margin-bottom: 12px; }
168	.section-head h2 { margin-bottom: 2px; }
169	.section-head p { color: var(--muted); margin: 0; font-size: 0.92rem; }
170	.muted { color: var(--muted); }
171	.small { font-size: 0.85rem; }
172	
173	.btn {
174	  display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 9px 16px;
175	  border-radius: var(--radius-sm); border: 1px solid var(--line-strong); background: var(--surface);
176	  color: var(--ink); font: inherit; font-weight: 600; font-size: 0.92rem; cursor: pointer; text-decoration: none;
177	  min-height: 40px;
178	}
179	.btn:hover:not(:disabled) { background: var(--surface-2); border-color: var(--muted); }
180	.btn:disabled { opacity: 0.55; cursor: not-allowed; }
181	.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
182	.btn.primary:hover:not(:disabled) { filter: brightness(0.93); background: var(--accent); }
183	.btn.small { padding: 5px 10px; min-height: 32px; font-size: 0.84rem; }
184	.btn-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
185	.link-btn {
186	  background: none; border: 0; padding: 0; color: var(--accent); font: inherit; cursor: pointer;
187	  text-decoration: underline;
188	}
189	
190	/* Pills, badges */
191	.pill {
192	  display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.8rem;
193	  font-weight: 600; white-space: nowrap; background: var(--tone-bg); color: var(--tone-fg);
194	  border: 1px solid transparent;
195	}
196	.pill::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--tone-bar); }
197	.pill.plain::before { display: none; }
198	.badge {
199	  display: inline-block; padding: 2px 9px; border-radius: var(--radius-sm); font-size: 0.78rem; font-weight: 700;
200	  background: var(--tone-bg); color: var(--tone-fg); letter-spacing: 0.02em;
201	}
202	.tone-good { --tone-fg: var(--good-fg); --tone-bg: var(--good-bg); --tone-bar: var(--good-bar); }
203	.tone-neutral { --tone-fg: var(--neutral-fg); --tone-bg: var(--neutral-bg); --tone-bar: var(--neutral-bar); }
204	.tone-caution { --tone-fg: var(--caution-fg); --tone-bg: var(--caution-bg); --tone-bar: var(--caution-bar); }
205	.tone-bad { --tone-fg: var(--bad-fg); --tone-bg: var(--bad-bg); --tone-bar: var(--bad-bar); }
206	.tone-info { --tone-fg: var(--info-fg); --tone-bg: var(--info-bg); --tone-bar: var(--info-bar); }
207	
208	.mode-synthetic { background: var(--caution-bg); color: var(--caution-fg); border: 1px solid var(--caution-bar); }
209	.mode-live { background: var(--info-bg); color: var(--info-fg); border: 1px solid var(--info-bar); }
210	
211	.banner {
212	  display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius);
213	  background: var(--tone-bg); color: var(--tone-fg); border: 1px solid var(--tone-bar); margin-bottom: 14px;
214	}
215	.banner svg { flex: none; margin-top: 2px; }
216	.banner strong { display: block; }
217	.banner p { margin: 0; }
218	.banner-demo { font-weight: 700; font-size: 1rem; }
219	
220	/* Forms */
221	.field { margin-bottom: 18px; }
222	.field label, .field .label, legend.label { display: block; font-weight: 600; margin-bottom: 4px; font-size: 0.93rem; }
223	.help { color: var(--muted); font-size: 0.84rem; margin: 4px 0 0; }
224	.input, .textarea, .select {
225	  width: 100%; font: inherit; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong);
226	  border-radius: var(--radius-sm); padding: 9px 11px; min-height: 40px;
227	}
228	.textarea { min-height: 96px; resize: vertical; }
229	.input[aria-invalid="true"], .textarea[aria-invalid="true"], .select[aria-invalid="true"] { border-color: var(--bad-bar); }
230	.input:disabled { background: var(--surface-2); }
231	.error-text { color: var(--bad-fg); font-size: 0.86rem; margin: 4px 0 0; font-weight: 500; }
232	.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
233	fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
234	.check { display: flex; gap: 10px; align-items: flex-start; }
235	.check input { width: 20px; height: 20px; margin-top: 2px; flex: none; accent-color: var(--accent); }
236	
237	.choice-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; }
238	.choice {
239	  display: block; position: relative; border: 2px solid var(--line); border-radius: var(--radius); padding: 14px 16px;
240	  background: var(--surface); cursor: pointer;
241	}
242	.choice:hover { border-color: var(--line-strong); }
243	.choice.selected { border-color: var(--accent); background: var(--accent-soft); }
244	.choice.disabled { opacity: 0.7; cursor: not-allowed; background: var(--surface-2); }
245	.choice input { position: absolute; opacity: 0; inset: 0; width: 100%; height: 100%; cursor: inherit; margin: 0; }
246	.choice:has(input:focus-visible) { outline: 3px solid var(--focus); outline-offset: 2px; }
247	.choice-title { font-weight: 700; display: flex; justify-content: space-between; gap: 8px; align-items: center; }
248	.choice-body { color: var(--ink-2); font-size: 0.9rem; margin: 6px 0 0; }
249	.choice-check { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--line-strong); flex: none; }
250	.choice.selected .choice-check { border-color: var(--accent); background: var(--accent); box-shadow: inset 0 0 0 3px var(--accent-soft); }
251	
252	.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
253	.chip {
254	  display: inline-flex; align-items: center; gap: 4px; background: var(--neutral-bg); color: var(--ink);
255	  border-radius: 999px; padding: 3px 4px 3px 11px; font-size: 0.86rem;
256	}
257	.chip button {
258	  border: 0; background: transparent; cursor: pointer; width: 22px; height: 22px; border-radius: 50%; color: inherit;
259	  display: inline-flex; align-items: center; justify-content: center;
260	}
261	.chip button:hover { background: rgba(0, 0, 0, 0.12); }
262	
263	/* Tables */
264	.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
265	.table-wrap table { min-width: 560px; }
266	th, td { text-align: left; padding: 9px 12px; border-bottom: 1px solid var(--line); vertical-align: top; font-size: 0.9rem; }
267	th { background: var(--surface-2); font-weight: 600; color: var(--ink-2); font-size: 0.82rem; white-space: nowrap; }
268	tr:last-child td { border-bottom: 0; }
269	td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
270	.pos { color: var(--good-fg); }
271	.neg { color: var(--bad-fg); }
272	.flag-list { list-style: none; padding: 0; margin: 4px 0 0; }
273	.flag-list li { color: var(--caution-fg); background: var(--caution-bg); border-radius: 4px; padding: 2px 8px; font-size: 0.8rem; margin-bottom: 3px; }
274	
275	/* Tabs */
276	.tabs { display: flex; gap: 4px; border-bottom: 2px solid var(--line); margin-bottom: 14px; flex-wrap: wrap; }
277	.tab {
278	  background: none; border: 0; border-bottom: 3px solid transparent; margin-bottom: -2px; padding: 9px 14px;
279	  font: inherit; font-weight: 600; color: var(--muted); cursor: pointer;
280	}
281	.tab:hover { color: var(--ink); }
282	.tab[aria-selected="true"] { color: var(--accent); border-bottom-color: var(--accent); }
283	.tab .count { font-weight: 500; opacity: 0.8; margin-left: 4px; }
284	
285	/* Disclosure */
286	details.disclosure { border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); margin-top: 10px; }
287	details.disclosure > summary {
288	  cursor: pointer; padding: 8px 12px; font-weight: 600; font-size: 0.88rem; color: var(--ink-2); list-style: none;
289	  display: flex; align-items: center; gap: 8px;
290	}
291	details.disclosure > summary::-webkit-details-marker { display: none; }
292	details.disclosure > summary::before {
293	  content: ""; width: 7px; height: 7px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
294	  transform: rotate(-45deg); transition: transform 0.15s; flex: none;
295	}
296	details.disclosure[open] > summary::before { transform: rotate(45deg); }
297	details.disclosure > .disc-body { padding: 4px 14px 12px; }
298	
299	/* Case header */
300	.case-head h1 { margin-bottom: 4px; word-break: break-word; }
301	.case-meta { display: flex; gap: 8px 12px; flex-wrap: wrap; align-items: center; margin: 8px 0; }
302	.peer-list { color: var(--ink-2); margin: 4px 0; }
303	.thesis { background: var(--surface-2); border-left: 3px solid var(--accent); padding: 10px 14px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0; white-space: pre-wrap; margin: 0; }
304	
305	/* Summary */
306	.summary { display: grid; grid-template-columns: minmax(200px, 260px) 1fr; gap: 28px; align-items: start; }
307	.score-box { text-align: center; padding: 18px 12px; border-radius: var(--radius); background: var(--tone-bg); color: var(--tone-fg); }
308	.score-num { font-size: 4rem; font-weight: 800; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
309	.score-num small { font-size: 1.1rem; font-weight: 600; opacity: 0.75; }
310	.score-none { font-size: 1.3rem; font-weight: 700; line-height: 1.25; padding: 10px 0; }
311	.score-band { font-size: 1.15rem; font-weight: 700; margin-top: 6px; }
312	.score-cap { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; margin-bottom: 6px; opacity: 0.85; }
313	.headline { font-size: 1.2rem; font-weight: 600; line-height: 1.4; margin-bottom: 16px; }
314	.meters { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
315	.meter-head { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; margin-bottom: 4px; }
316	.meter-name { font-weight: 700; font-size: 0.9rem; }
317	.meter-val { font-weight: 700; font-variant-numeric: tabular-nums; }
318	.meter-track { height: 12px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; position: relative; }
319	.meter-fill { height: 100%; border-radius: 999px; background: var(--tone-bar); }
320	.meter-sub { font-size: 0.84rem; color: var(--muted); margin-top: 3px; }
321	.infobox { background: var(--info-bg); color: var(--ink); border: 1px solid var(--info-bar); border-radius: var(--radius-sm); padding: 10px 14px; margin-top: 16px; font-size: 0.9rem; }
322	.infobox strong { color: var(--info-fg); display: block; margin-bottom: 2px; }
323	.infobox p { margin: 0; }
324	
325	/* Signals */
326	.signals { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 16px; }
327	.signal { display: flex; flex-direction: column; margin: 0 !important; }
328	.signal-head { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; }
329	.signal-name { font-size: 1.02rem; margin: 0; }
330	.signal-q { color: var(--muted); font-size: 0.88rem; margin: 2px 0 10px; font-style: italic; }
331	.bar-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; }
332	.bar-track { flex: 1; height: 10px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; }
333	.bar-fill { height: 100%; background: var(--tone-bar); border-radius: 999px; }
334	.bar-val { font-weight: 700; min-width: 4.5em; text-align: right; font-variant-numeric: tabular-nums; font-size: 0.9rem; }
335	.kv { display: flex; gap: 14px; flex-wrap: wrap; color: var(--muted); font-size: 0.84rem; margin-bottom: 8px; }
336	.signal .finding-text-plain { margin-bottom: 8px; }
337	.signal h4 { margin: 10px 0 2px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
338	.signal ul.lim { color: var(--ink-2); font-size: 0.88rem; margin: 2px 0 0; }
339	.tech-list { font-family: var(--mono); font-size: 0.8rem; word-break: break-word; }
340	
341	/* Findings */
342	.finding-group + .finding-group { margin-top: 20px; }
343	.finding-group > h3 { display: flex; gap: 8px; align-items: baseline; }
344	.finding-group > h3 .muted { font-weight: 400; font-size: 0.85rem; }
345	.finding { margin-top: 10px !important; border-left: 4px solid var(--tone-bar); padding: 14px 16px; }
346	.finding-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 6px; }
347	.finding-text { font-weight: 600; margin: 0 0 8px; font-size: 1rem; }
348	.finding h4 { margin: 10px 0 2px; font-size: 0.85rem; color: var(--ink-2); }
349	.finding ul { margin: 2px 0 0; font-size: 0.9rem; color: var(--ink-2); }
350	.ev-list { list-style: none; padding: 0 !important; }
351	.ev-item { padding: 6px 10px; background: var(--surface-2); border-radius: var(--radius-sm); margin-bottom: 4px; border-left: 3px solid var(--good-bar); }
352	.ev-item.counter { border-left-color: var(--bad-bar); background: var(--bad-bg); }
353	.ev-label { font-weight: 600; font-size: 0.88rem; color: var(--ink); }
354	.ev-meta { color: var(--muted); font-size: 0.8rem; }
355	.ev-item.counter .ev-meta { color: var(--bad-fg); }
356	
357	/* Questions */
358	.question-list { padding-left: 0; list-style: none; counter-reset: q; }
359	.question-list li { counter-increment: q; display: flex; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); margin: 0; }
360	.question-list li:last-child { border-bottom: 0; }
361	.question-list li::before {
362	  content: counter(q); flex: none; width: 26px; height: 26px; border-radius: 50%; background: var(--accent-soft); color: var(--accent);
363	  font-weight: 700; display: inline-flex; align-items: center; justify-content: center; font-size: 0.85rem;
364	}
365	
366	/* Timeline */
367	.timeline { list-style: none; padding: 0; margin: 0; position: relative; }
368	.timeline li { position: relative; padding: 0 0 18px 30px; margin: 0; }
369	.timeline li::before { content: ""; position: absolute; left: 9px; top: 18px; bottom: -2px; width: 2px; background: var(--line); }
370	.timeline li:last-child::before { display: none; }
371	.tl-dot { position: absolute; left: 2px; top: 4px; width: 16px; height: 16px; border-radius: 50%; background: var(--tone-bar); border: 3px solid var(--surface); box-shadow: 0 0 0 1px var(--tone-bar); }
372	.tl-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
373	.tl-title { font-weight: 600; }
374	.tl-detail { color: var(--ink-2); margin: 2px 0 0; font-size: 0.9rem; }
375	.tl-meta { color: var(--muted); font-size: 0.8rem; display: flex; gap: 12px; flex-wrap: wrap; margin-top: 2px; }
376	.actor { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 1px 8px; border-radius: 4px; background: var(--tone-bg); color: var(--tone-fg); }
377	
378	/* Progress */
379	.progress-panel { border-left: 5px solid var(--accent); }
380	.progress-q { font-size: 1.05rem; font-weight: 600; margin: 6px 0 12px; }
381	.spinner {
382	  width: 18px; height: 18px; border-radius: 50%; border: 3px solid var(--line-strong); border-top-color: var(--accent);
383	  animation: spin 0.9s linear infinite; display: inline-block; flex: none;
384	}
385	@keyframes spin { to { transform: rotate(360deg); } }
386	@media (prefers-reduced-motion: reduce) { .spinner { animation-duration: 3s; } html { scroll-behavior: auto; } }
387	.progress-head { display: flex; align-items: center; gap: 10px; font-weight: 700; }
388	.live-steps { max-height: 320px; overflow: auto; margin-top: 8px; padding-top: 4px; }
389	
390	/* Cost */
391	.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
392	.stat { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 10px 12px; }
393	.stat-v { font-size: 1.4rem; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.2; }
394	.stat-k { color: var(--muted); font-size: 0.82rem; }
395	.cols-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
396	.cols-2 > .card { margin: 0 !important; }
397	.trace-row { display: flex; gap: 8px; align-items: center; margin-bottom: 6px; flex-wrap: wrap; }
398	.trace-id { font-family: var(--mono); font-size: 0.82rem; background: var(--surface-2); border: 1px solid var(--line); padding: 3px 8px; border-radius: 4px; word-break: break-all; }
399	
400	/* States */
401	.state { text-align: center; padding: 36px 16px; color: var(--muted); }
402	.state .spinner { margin-bottom: 8px; }
403	.error-box { background: var(--bad-bg); color: var(--bad-fg); border: 1px solid var(--bad-bar); border-radius: var(--radius); padding: 12px 14px; }
404	.error-box strong { display: block; }
405	.empty-box { padding: 18px; text-align: center; color: var(--muted); border: 1px dashed var(--line-strong); border-radius: var(--radius); background: var(--surface); }
406	
407	/* Cases list */
408	.case-link { font-weight: 600; text-decoration: none; }
409	.case-link:hover { text-decoration: underline; }
410	
411	/* Featured cases */
412	.featured { margin-top: 24px; }
413	.featured h2 { font-size: 1.05rem; }
414	.featured-list { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; }
415	.featured-list li { margin: 0; padding: 12px 14px; border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); }
416	.featured-list p { margin: 4px 0 0; }
417	
418	/* Stop confirmation */
419	.confirm-box { margin-top: 12px; padding: 12px 14px; border: 1px solid var(--caution-bar); background: var(--caution-bg); color: var(--caution-fg); border-radius: var(--radius-sm); }
420	.confirm-box p { margin: 0 0 8px; font-weight: 600; }
421	.row-check { width: 20px; height: 20px; accent-color: var(--accent); }
422	
423	/* Evidence page */
424	.shot-grid { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }
425	.shot-grid li { margin: 0; }
