/* Trace waterfall */
.tw {
  --k-llm-fg: #5b3a99; --k-llm-bg: #ece6f8; --k-llm-bar: #8a68c9;
  --k-chain-fg: #0f5d57; --k-chain-bg: #dcefed; --k-chain-bar: #3a9b93;
}
@media (prefers-color-scheme: dark) {
  .tw {
    --k-llm-fg: #cdb9f5; --k-llm-bg: #2a1f45; --k-llm-bar: #9b7fd8;
    --k-chain-fg: #8fe0d6; --k-chain-bg: #123a3a; --k-chain-bar: #36b7ac;
  }
}
.tw .k-workflow { --k-fg: var(--neutral-fg); --k-bg: var(--neutral-bg); --k-bar: var(--neutral-bar); }
.tw .k-agent { --k-fg: var(--info-fg); --k-bg: var(--info-bg); --k-bar: var(--info-bar); }
.tw .k-tool { --k-fg: var(--good-fg); --k-bg: var(--good-bg); --k-bar: var(--good-bar); }
.tw .k-chain { --k-fg: var(--k-chain-fg); --k-bg: var(--k-chain-bg); --k-bar: var(--k-chain-bar); }
.tw .k-guardrail { --k-fg: var(--caution-fg); --k-bg: var(--caution-bg); --k-bar: var(--caution-bar); }
.tw .k-llm { --k-fg: var(--k-llm-fg); --k-bg: var(--k-llm-bg); --k-bar: var(--k-llm-bar); }
.tw .k-other { --k-fg: var(--neutral-fg); --k-bg: var(--neutral-bg); --k-bar: var(--neutral-bar); }
.tw-head { display: flex; flex-wrap: wrap; gap: 8px 20px; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.tw-id { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; min-width: 0; }
.tw-stats { display: flex; flex-wrap: wrap; gap: 6px 16px; align-items: center; font-size: 0.88rem; }
.tw-controls { display: flex; flex-wrap: wrap; gap: 8px 20px; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.tw-legend { margin: 0; color: var(--muted); font-size: 0.88rem; }
.tw-filter { font-size: 0.88rem; font-weight: 600; align-items: center; }
.tw-filter input { width: 18px; height: 18px; margin-top: 0; }
.tw-desc { margin: 0 0 12px; color: var(--ink-2); font-size: 0.92rem; }
.tw-list { list-style: none; margin: 0; padding: 0; border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); overflow: hidden; }
.tw-item { margin: 0; padding: 0; border-bottom: 1px solid var(--line); }
.tw-item:last-child { border-bottom: 0; }
.tw-item.failed { background: var(--bad-bg); }
.tw-line { display: flex; align-items: stretch; }
.tw-toggle, .tw-toggle-spacer { flex: none; width: 26px; }
.tw-toggle { background: none; border: 0; padding: 0; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; color: var(--muted); }
.tw-toggle:hover { color: var(--ink); background: rgba(127, 127, 127, 0.12); }
.tw-chevron { width: 7px; height: 7px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(-45deg); transition: transform 0.15s; }
.tw-chevron.open { transform: rotate(45deg); }
.tw-main {
  flex: 1; min-width: 0; display: grid; grid-template-columns: 92px minmax(120px, 36%) minmax(0, 1fr) 74px; gap: 10px;
  align-items: center; background: none; border: 0; font: inherit; color: inherit; text-align: left; padding: 7px 10px 7px 4px; cursor: pointer;
