.tw-bar.failed { background: var(--bad-bar); }
.tw-tick { position: absolute; top: -2px; bottom: -2px; width: 3px; margin-left: -1px; background: var(--ink); border-radius: 1px; opacity: 0.85; }
.tw-dur { text-align: right; font-size: 0.82rem; font-variant-numeric: tabular-nums; color: var(--ink-2); white-space: nowrap; }
