.tw-details { margin: 0 10px 10px 0; padding: 10px 12px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-sm); font-size: 0.86rem; }
.tw-detail-meta { color: var(--muted); font-size: 0.82rem; margin-bottom: 6px; }
.tw-attrs { width: 100%; }
.tw-attrs th, .tw-attrs td { padding: 3px 8px 3px 0; border-bottom: 0; background: none; font-size: 0.82rem; white-space: normal; word-break: break-word; }
.tw-attrs th { font-family: var(--mono); font-weight: 600; color: var(--ink-2); width: 40%; }
.tw-h { margin: 10px 0 2px; font-size: 0.82rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; }
.tw-events { margin: 0; padding-left: 1.2em; font-size: 0.84rem; }
.tw.compact .tw-main { padding-top: 4px; padding-bottom: 4px; }
@media (max-width: 640px) {
  .tw-main { grid-template-columns: 78px minmax(0, 1fr) auto; }
  .tw-track { display: none; }
